function alpha_star_exact(G = (V, E)):
    n <- |V|
    best_val <- 0                         # x == 0 is always feasible
    best_x   <- (0, ..., 0)
    for x in {0, 1/2, 1}^n:               # half-integral grid
        feasible <- true
        for (u, v) in E:
            if x[u] + x[v] > 1: feasible <- false; break
        if not feasible: continue
        val <- sum(x)
        if val > best_val:
            best_val <- val; best_x <- x
    return (best_val, best_x)
